// magicraft-core compiled to wasm (crates/core-wasm → ./pkg, generated by
// `pnpm -C app build:wasm` and committed). The browser loads it with `loadCore()` (Vite
// serves `pkg/core_bg.wasm` as an asset); Vitest initializes it synchronously from the file
// (`src/wasm/setup.node.ts`). Every other function here needs one of those first.
import init, * as pkg from "./pkg/core.js";

let loading: Promise<void> | null = null;
let ready = false;

/** Loads the wasm module once (browser: fetches the asset). */
export function loadCore(): Promise<void> {
  loading ??= init().then(() => {
    ready = true;
  });
  return loading;
}

/** Synchronous init from the module bytes (Node / tests). */
export function initCoreSync(bytes: BufferSource) {
  if (ready) return;
  pkg.initSync({ module: bytes });
  ready = true;
}

export const coreReady = () => ready;

function need() {
  if (!ready) throw new Error("magicraft core wasm is not loaded (loadCore())");
}

/** `physics::MoveError` names by wasm result code (`1 + discriminant`). */
export const MOVE_ERRORS = ["", "MoveTooFast", "Collision", "NotOnGround", "Flying", "InvalidMoveState", "TimeSkew"] as const;
export type MoveErrorName = Exclude<(typeof MOVE_ERRORS)[number], "">;

export const MOVE_STATE_BYTES = 72;
export const CHUNK_BYTES = 16_384;

export type CheckResult =
  | { ok: true; fallDamage: number; state: Uint8Array }
  | { ok: false; error: MoveErrorName | "BadInput" };

/** Block window for `checkMove`: origin + 4 slots `(cx0,cz0)`, `(cx0+1,cz0)`,
 *  `(cx0,cz0+1)`, `(cx0+1,cz0+1)`; a null slot reads as Stone (not passed to the program). */
export type Quad = { cx0: number; cz0: number; slots: (Uint8Array | null)[] };

const quadBuf = new Uint8Array(4 * CHUNK_BYTES);

/** `physics::check_move` (exactly the program's). Times in chain ms. */
export function checkMove(
  params: Uint8Array,
  prev: Uint8Array,
  pos: readonly number[],
  vel: readonly number[],
  onGround: boolean,
  clientMs: number,
  chainMs: number,
  quad: Quad,
): CheckResult {
  need();
  let mask = 0;
  quad.slots.forEach((s, i) => {
    if (!s) return;
    quadBuf.set(s, i * CHUNK_BYTES);
    mask |= 1 << i;
  });
  const r = pkg.check_move(
    params,
    prev,
    Int32Array.from(pos),
    Int32Array.from(vel),
    onGround,
    Math.floor(clientMs),
    Math.floor(chainMs),
    quad.cx0,
    quad.cz0,
    quadBuf,
    mask,
  );
  if (r[0] === 0) return { ok: true, fallDamage: r[1], state: r.slice(2) };
  return { ok: false, error: r[0] === 255 ? "BadInput" : (MOVE_ERRORS[r[0]] as MoveErrorName) };
}

/** `physics::move_window(a, b)` (FP positions), or null if it spans more than 2×2 chunks. */
export function coreMoveWindow(a: readonly number[], b: readonly number[]): [number, number] | null {
  need();
  const r = pkg.move_window(Int32Array.from(a), Int32Array.from(b));
  return r.length === 2 ? [r[0], r[1]] : null;
}

/** `blocks::BLOCK_FLAGS` (bit 1 solid, 2 transparent, 4 fluid). */
export function blockFlags(): Uint8Array {
  need();
  return pkg.block_flags();
}

/** `WorldParams::default()` bytes. */
export function defaultParamsBytes(): Uint8Array {
  need();
  return pkg.default_params();
}

/** `WorldParams::validate`: −1 valid, else the `ParamError` discriminant. */
export function validateParamsBytes(b: Uint8Array): number {
  need();
  return pkg.validate_params(b);
}

/** `MoveState::spawn(pos, nowMs)` bytes (optionally on ground). */
export function spawnState(pos: readonly number[], nowMs: number, onGround = false): Uint8Array {
  need();
  return pkg.spawn_state(Int32Array.from(pos), nowMs, onGround);
}

export const coreVersion = () => (need(), pkg.core_version());
